CREATE TABLE trials (  subject TEXT PRIMARY KEY NOT NULL CHECK(length(subject) BETWEEN 1 AND 128),  status TEXT NOT NULL CHECK(status IN ('used','blocked')),  started_at INTEGER,  expires_at INTEGER,  CHECK((status='blocked' AND started_at IS NULL AND expires_at IS NULL) OR        (status='used' AND typeof(started_at)='integer' AND started_at>=0 AND typeof(expires_at)='integer' AND expires_at=started_at+1296000000)) );
CREATE TRIGGER trials_immutable BEFORE UPDATE ON trials  BEGIN SELECT RAISE(ABORT,'Trial records are immutable; never reset a used trial'); END;
CREATE TRIGGER trials_retained BEFORE DELETE ON trials  BEGIN SELECT RAISE(ABORT,'Trial history must be retained'); END;
CREATE TABLE licenses (  subject TEXT NOT NULL CHECK(length(subject) BETWEEN 1 AND 128),  source TEXT NOT NULL CHECK(source IN ('GOOGLE_PLAY_PURCHASE','ADMIN_GIFT')),  status TEXT NOT NULL CHECK(status IN ('active','revoked')),  permanent INTEGER NOT NULL CHECK(permanent IN (0,1)),  expires_at INTEGER,  purchase_token_hash TEXT UNIQUE,  PRIMARY KEY(subject,source),  CHECK((permanent=1 AND expires_at IS NULL) OR        (source='ADMIN_GIFT' AND permanent=0 AND typeof(expires_at)='integer' AND expires_at>=0)),  CHECK(source!='GOOGLE_PLAY_PURCHASE' OR permanent=1) );
CREATE TABLE identity_policy (  subject TEXT PRIMARY KEY NOT NULL CHECK(length(subject) BETWEEN 1 AND 128),  blocked INTEGER NOT NULL DEFAULT 0 CHECK(blocked IN (0,1)),  tokens_valid_after INTEGER NOT NULL DEFAULT 0 CHECK(typeof(tokens_valid_after)='integer' AND tokens_valid_after>=0) );
